"""Random arrays for index_of_max.

Deliberately weighted towards the two things that go wrong: ties, which the
first-wins rule turns on, and all-negative arrays, where an unsigned
comparison gives a confidently wrong answer.
"""

LOW, HIGH = -200, 200


def generate(rng, count):
    builders = (_mixed, _with_a_tie, _all_negative, _max_at_an_end)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n" % (len(values),
                                " ".join(str(v) for v in values)),
        "description": description,
    }


def _mixed(rng, index):
    values = [rng.randint(LOW, HIGH) for _ in range(rng.randint(5, 14))]
    return _case("mixed values #%d" % index, values)


def _with_a_tie(rng, index):
    # Build the array below the peak, then plant the same peak twice so the
    # tie is a fact about the input rather than something to hope for.
    values = [rng.randint(LOW, HIGH - 1) for _ in range(rng.randint(6, 14))]
    first, second = sorted(rng.sample(range(len(values)), 2))
    values[first] = values[second] = HIGH
    return _case("repeated maximum #%d" % index, values,
                 "The largest value appears at %d and %d; the answer is the "
                 "earlier one." % (first, second))


def _all_negative(rng, index):
    values = [rng.randint(LOW, -1) for _ in range(rng.randint(5, 14))]
    return _case("all negative #%d" % index, values,
                 "Every value has its top bit set, so an unsigned comparison "
                 "picks the wrong one.")


def _max_at_an_end(rng, index):
    values = [rng.randint(LOW, HIGH - 1) for _ in range(rng.randint(5, 14))]
    position = 0 if index % 2 else len(values) - 1
    values[position] = HIGH
    return _case("largest at index %d #%d" % (position, index), values,
                 "The largest element sits at one end of the array.")
